const $=id=>document.getElementById(id);let report,index=0;const ratings=[];
const order=[];const el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};
function render(){const c=report.cases[index];$('case').value=index;$('evidence').textContent=JSON.stringify(c.input,null,2);$('pair').replaceChildren();for(const[side,arm]of order[index].entries()){const box=el('article','');box.className='arm';box.append(el('h2',side?'B':'A'));const data=c[arm];if(data.error)box.append(el('p','This arm failed: '+data.error));for(const[role,p]of Object.entries(data.posts||{}))box.append(el('h3',role),el('p',p.text),el('small','Source: '+p.evidence_id));for(const[metric,label]of [['grounding','Supported by the evidence'],['clarity','Easy to understand'],['usefulness','Adds useful football understanding']]){const l=el('label',label),select=el('select','');select.dataset.arm=arm;select.dataset.metric=metric;for(const[v,t]of [['','Not rated'],['1','1 — Poor'],['2','2'],['3','3 — Adequate'],['4','4'],['5','5 — Excellent']]){const option=el('option',t);option.value=v;select.append(option);}select.value=ratings[index]?.[arm]?.[metric]||'';l.append(select);box.append(l);}$('pair').append(box);}}
function save(){const row={case:report.cases[index].input.id};for(const select of $('pair').querySelectorAll('select')){row[select.dataset.arm]??={};row[select.dataset.arm][select.dataset.metric]=select.value?Number(select.value):null;}ratings[index]=row;}
$('case').onchange=()=>{save();index=Number($('case').value);render();};$('next').onclick=()=>{save();index=(index+1)%report.cases.length;render();$('status').textContent='Rating saved in this session. Export to keep it.';};$('export').onclick=()=>{save();const blob=new Blob([JSON.stringify({study:report.version,recorded_at:new Date().toISOString(),ratings,limitation:'Self-submitted browser ratings; reviewer independence and identity not verified.'},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a','');a.href=url;a.download='btr-editorial-ratings.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
try{const r=await fetch('assets/tracking/commentary-comparison.json');if(!r.ok)throw Error('Comparison unavailable');report=await r.json();if(!report.cases?.length)throw Error(report.reason||'Live comparison is pending');for(const[i,c]of report.cases.entries()){order.push(crypto.getRandomValues(new Uint8Array(1))[0]%2?['crew','baseline']:['baseline','crew']);const o=el('option',c.input.id);o.value=i;$('case').append(o);}$('method').textContent=report.method;$('status').textContent='Independent review pending. No winner has been established.';render();}catch(e){$('status').textContent=e.message;$('next').disabled=$('export').disabled=true;}
